type User = {
  id: number
};
function isUser(v: unknown): v is User {
  return typeof v === 'object' && v !== null && 'id' in v && typeof v.id === 'number';
}

type Result = {
  ok: true;
  value: string
} | {
  ok: false;
  error: string
};
function show(r: Result) {
  return r.ok ? r.value : r.error
}

type State = 'todo' | 'done';
function label(s: State): string {
  switch (s) {
    case 'todo': return '未完';
    case 'done': return '完了';
    default:
      const neverValue: never = s;
      return neverValue;
  }
}

